@startuml

class City {}

class Location {
  + CityName : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + Description : string
  + RequestedDate : date
  + RequestedTime : time
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class Route {
  + RouteDate : date
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class Item {
  + Description : string
  + Weight : float
  + Dimensions : string
}

class SecondHandArticle {
  + RFIDTag : string
  + Category : string
}

class NonPerishableFood {}

class DistributionCenter {
}

class Employee {
  + EmployeeID : string
  + Name : string
}

class Client {
  + Name : string
  + HomeAddress : string
}

class Category {
  + CategoryName : string
}

class Delivery {
  + DeliveryDate : date
}

City "1" -- "0..*" Location
Location "1" *-- "1" DistributionCenter
Resident "1" -- "0..*" PickupRequest
PickupRequest "1" -- "1..*" Item
Vehicle "1" -- "0..*" Route
VolunteerDriver "1" -- "0..*" Route
Route "1" -- "1..*" PickupRequest
Item "1" -- "0..1" SecondHandArticle
Item "1" -- "0..1" NonPerishableFood
DistributionCenter "1" -- "0..*" SecondHandArticle
Employee "1" -- "0..*" SecondHandArticle
Category "1" -- "0..*" SecondHandArticle
Client "1" -- "0..*" Delivery
Delivery "1" -- "0..*" SecondHandArticle
VolunteerDriver "1" -- "0..*" Delivery

@enduml

